export function getFamily(slug) {
  return FAMILIES.find((f) => f.slug === slug);
}

export function itemsForFamily(slug) {
  return catalogItems.filter((i) => i.family === slug);
}

export function getItem(slug) {
  return catalogItems.find((i) => i.slug === slug);
}
